import reference from '../../../docs/ValidationStudies/Skeem1979IndependentVerificationStage5C6A.json';
import { calcSkeemPostImpact } from '../../engineering/jar/skeemDynamics';
import { calculateJarPerformance } from './skeemPerformance';
import { samplePrimaryForceHistory, primaryForcePlot } from './primaryForceHistory';

// Expected values are generated by the adjacent Python Decimal reference using
// closed geometric sums, not this solver, adapter, sampler or their helpers.
const close = (actual, expected) => expect(Math.abs(actual - expected)).toBeLessThan(1e-10 * Math.max(1, Math.abs(expected)));

test.each(Object.entries(reference.cases))('%s agrees with independently generated 60-digit reference', (name, { input, expected: e }) => {
  const r = calcSkeemPostImpact(input);
  expect(r.valid).toBe(true);
  ['AcIn2', 'ApIn2', 'alpha', 'vcFtS', 'completedReflections', 'hammerVelocityFtS', 'impactTimeS'].forEach(key => close(r.preImpact[key], e[key]));
  close(r.preImpact.lambda, e.lambdaValue);
  ['impactForceLbf', 'initialStuckPointForceLbf', 'residualIncidentForceLbf', 'residualStuckPointIncrementLbf',
    'primaryPulseDurationS', 't1S', 't2S', 't3S', 'impulseLbfS', 'averageStuckPointForceLbf'].forEach(key => close(r[key], e[key]));
  close(r.forceTimeEvents[1].relativeTimeS, e.residualDelayS);
  expect(r.t1S).toBeLessThan(r.t2S); expect(r.t2S).toBeLessThan(r.t3S);
  close(r.forceHistory[0].impulseLbfS, e.firstIntervalImpulseLbfS);
  close(r.forceHistory[1].impulseLbfS, e.secondIntervalImpulseLbfS);
  for (const n of [1, 8, 32, 1024]) {
    const h = samplePrimaryForceHistory(r, n), plot = primaryForcePlot(h, true);
    close(h.peakForceLbf, e.peakForceLbf);
    close(h.numericalImpulseLbfS, e.impulseLbfS);
    expect(h.samples[0].cumulativeImpulseLbfS).toBe(0);
    h.samples.forEach(p => close(p.cumulativeImpulseLbfS,
      e.initialStuckPointForceLbf * p.timeS + e.residualStuckPointIncrementLbf * Math.max(0, p.timeS - e.residualDelayS)));
    close(plot.data[2].y.at(-1), e.impulseLbfS);
    expect(plot.data[2].y[0]).toBe(0);
    expect(plot.layout.yaxis.title.text).toBe('Stuck-Point Force (klbf)');
    expect(plot.layout.annotations.some(a => a.text.includes('Residual tensile wave'))).toBe(true);
  }
});

test('existing Test 4 geometry and supplied operating inputs reproduce rounded user reference through UI adapter', () => {
  const demo = require('../../../docs/ValidationStudies/JarPlacementDemoStage5C1.json');
  const bha = demo.storage.drillbenchWell.currentBha;
  // Stuck point at MD 11995: 5 ft above bit, base of lower DC; excludes STB.
  const r = calculateJarPerformance(bha, { strokeIn: '7', overpullKlbf: '300', stuckPointFt: '5' });
  expect(r.valid).toBe(true);
  expect(r.input).toEqual(reference.cases.test4Reference.input);
  const e = reference.cases.test4Reference.expected;
  close(r.impulseLbfS, e.impulseLbfS);
  expect(r.impactForceKlbf.toFixed(1)).toBe('488.3');
  expect((samplePrimaryForceHistory(r).peakForceLbf / 1000).toFixed(1)).toBe('1090.6');
  expect(r.averageStuckPointForceKlbf.toFixed(1)).toBe('1029.1');
  expect(r.impulseLbfS.toFixed(0)).toBe('23155');
  expect(r.preImpact.hammerVelocityFtS.toFixed(1)).toBe('15.3');
  expect((r.preImpact.impactTimeS * 1000).toFixed(2)).toBe('59.96');
  expect((r.primaryPulseDurationS * 1000).toFixed(2)).toBe('22.50');
});

test('independent impedance coefficients satisfy continuity and energy conservation', () => {
  const e = reference.cases.test4Reference.expected;
  close(1 + e.forceReflectionCoefficient, e.forceTransmissionCoefficient);
  close(1 - e.forceReflectionCoefficient, e.velocityTransmissionCoefficient);
  // Force-wave energy flux is proportional to F^2 / Z; Zc/Zp = alpha.
  close(e.forceReflectionCoefficient ** 2 + e.alpha * e.forceTransmissionCoefficient ** 2, 1);
});
